"""Exhaust all symmetries of a regular n-gon, Atanasyan 7–9, printed p. 327."""
import argparse
import json
from math import cos,sin,pi,radians
from rotation_constructions import turning_arrow
from rotated_circles_lines import diagram
from translations_and_rotations import lesson
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/regular-polygon-symmetries.json'


def drawing(title,n,r,phase,mode,steps=1):
    phi=radians(phase);points={'T':(0,0)};names=['A','B',*[f'v{i}' for i in range(2,n)]]
    for i,name in enumerate(names):
        t=phi+2*pi*i/n;points[name]=(r*cos(t),r*sin(t))
    edges=[(a,names[(i+1)%n]) for i,a in enumerate(names)]
    if mode=='axes':
        guides=[]
        for k in range(n):
            t=phi+k*pi/n
            x,y=(r+.22)*cos(t),(r+.22)*sin(t)
            guides.append(((-x,-y),(x,y)))
    else:
        target=names[steps%n]
        points['E']=points[target]
        edges.extend([('T','A'),('T','E')])
        guides=turning_arrow((0,0),points['A'],steps*360/n)
    return diagram(title,points,edges,guides)


def clean(card):
    m=card['visualization']['model']
    for view in m['views'].values():
        visible=[]
        for key in view['points']:
            if key not in m['labels']:continue
            labels=[s for s in m['labels'][key].split('=') if not s.startswith('v')]
            if labels:
                m['labels'][key]='='.join(labels);visible.append(key)
        view['points']=visible
    return card


def axes():
    return clean(lesson(1272,None,327,'Сколько различных осей отражения имеет правильный n-угольник? Объясни ответ и для чётного, и для нечётного числа вершин.',
       'Все оси проходят через центр T описанной окружности: при отражении центр этой окружности должен сохраниться. Пусть правильный n-угольник имеет n≥3 вершин. Через центр и каждую вершину проходит ось, потому что точки на окружности расставлены равными угловыми шагами. Так же осью является прямая через центр и середину любой стороны. У нечётного n каждая ось соединяет вершину с серединой противоположной стороны: всего n осей. У чётного n получаем n/2 осей через пары противоположных вершин и n/2 осей через середины противоположных сторон. Других осей нет: отражение обязано переставлять вершины, а образ одной вершины определяет зеркальную перестановку всех остальных.',
       [('Рассмотри нечётный пример','У пятиугольника напротив вершины оказывается середина стороны. Проследи пары равноудалённых от оси вершин с обеих сторон. Для каждой из пяти вершин получается своя ось.','Отражение в прямой через две произвольные вершины не обязано совмещать правильный многоугольник с собой.'),
        ('Не посчитай одну ось дважды','У шестиугольника через центр и две противоположные вершины проходит одна прямая. Середины противоположных сторон также объединяются парами. Посчитай оси второго типа.','Число концов у оси внутри рисунка не превращает одну прямую в две разные оси.'),
        ('Обобщи на n','На третьей схеме семь вершин. Подсчитай оси, затем запиши общий ответ для чётного и нечётного n. Образ выбранной вершины даёт не более n вариантов отражения.','Считаем только прямые осевой симметрии, а не повороты вокруг центра.')],
       [drawing('Пять вершин',5,3,90,'axes'),drawing('Шесть вершин',6,3,0,'axes'),drawing('Семь вершин',7,3,90,'axes')],
       [('Сколько осей шестиугольника проходят через середины противоположных сторон?','3','Шесть середин сторон объединяются в три противоположные пары.'),('Сколько осей у правильного семиугольника?','7','У каждой из семи вершин своя ось через середину противоположной стороны.')],
       'Ось переставляет вершины в обратном порядке обхода. Зная образ одной вершины, можно определить образы обеих соседних с учётом этого порядка.',
       'Отдели оси через вершины от осей через середины сторон и учти совпадения прямых.',
       'Через T проведены все оси изображённого многоугольника. A и B — две соседние вершины.',
       'Назови общее число осей и объясни их расположение в чётном и нечётном случаях.',refs=[126,127]))


def enumerate_symmetries(part):
    if part=='а':
        cases=[(5,3,90,'axes',1),(5,3,90,'turn',2),(5,4,40,'turn',-1)]
        task='Перечисли все внутренние симметрии правильного пятиугольника.'
        proof='Есть пять отражений в прямых через вершину, центр и середину противоположной стороны. Повороты вокруг центра на 72°, 144°, 216° и 288° в одном выбранном направлении тоже совмещают фигуру с собой. Полного оборота в списке нет: он совпадает с тождественным движением. Всего девять внутренних симметрий. Других не бывает: для образа одной вершины есть пять вариантов; заданный прямой или обратный порядок обхода определяет затем все вершины.'
        steps=[('Расположи зеркальные оси','У пяти вершин пять собственных осей. Одна из сторон напротив каждой вершины делится этой осью пополам.','Пяти диагоналей недостаточно назвать осями: оси проходят через центр.'),
               ('Применяй шаг 72°','Полный оборот разбит на пять равных углов. На второй схеме E отстоит от A на два шага против часовой стрелки.','Два шага — это не два полных оборота.'),
               ('Разбери поворот в другую сторону','На третьем рисунке один шаг по часовой стрелке даёт тот же результат, что четыре шага против неё. Добавь к пяти отражениям все различные нетождественные повороты.','Не включай дополнительно повороты по часовой стрелке, если они уже встречаются в перечне в другом направлении.')]
        probes=[('На сколько градусов повернулось направление за два шага во второй схеме?','144','Два раза по 72°.'),('Сколько всего внутренних симметрий у пятиугольника?','9','Пять отражений и четыре нетождественных поворота.')]
    elif part=='б':
        cases=[(6,3,0,'axes',1),(6,3,15,'turn',1),(6,4,15,'turn',3)]
        task='Найди все внутренние симметрии правильного шестиугольника.'
        proof='Три оси проходят через противоположные вершины, ещё три — через середины противоположных сторон. Повороты вокруг центра на 60°, 120°, 180°, 240° и 300° при одном выбранном направлении дают пять нетождественных поворотов. Полуоборот среди них — центральная симметрия, его не считают дважды. Итого одиннадцать. Любое движение, сохраняющее многоугольник, переставляет вершины, сохраняя или обращая порядок обхода. Все двенадцать таких перестановок, включая тождественную, перечислены.'
        steps=[('Найди шесть осей','На первом рисунке выдели три прямые через противоположные вершины, затем три прямые через середины сторон.','Оси через середины не проходят через вершины, но всё равно отражают фигуру в себя.'),
               ('Построй наименьший ненулевой поворот','A и B — соседние вершины. На второй схеме E совпадает с B. От A до неё один из шести одинаковых углов у T.','Нужно делить полный, а не развёрнутый угол.'),
               ('Найди полуоборот в списке','В третьем примере A переходит в противоположную вершину E. Передвинувшись ещё на три шага, вернёшься к A. Посчитай все повороты и отражения без тождественного.','Центральная симметрия совпадает с одним из пяти поворотов — на 180°.')]
        probes=[('Сколько градусов содержит один шаг между соседними вершинами?','60','Раздели 360° на 6.'),('Сколько внутренних симметрий в сумме у шестиугольника?','11','Шесть отражений и пять нетождественных поворотов.')]
    else:
        cases=[(4,3,45,'axes',1),(7,3,90,'turn',1),(9,4,90,'turn',2)]
        task='Найди все внутренние симметрии правильного n-угольника и вырази их число через n.'
        proof='Для n≥3 имеется n отражений в осях правильного многоугольника. Повороты вокруг центра имеют углы k·360°/n, где k=1,…,n−1. Они дают ещё n−1 нетождественных движений. Всего 2n−1. Полнота списка следует из порядка обхода. Образ выбранной вершины может быть любой из n вершин. Затем соседняя вершина переходит к одному из двух соседей её образа, а остальные образы однозначны. Вместе с тождественным получилось ровно 2n возможных движений. Полуоборот сохраняет фигуру только при чётном n.'
        steps=[('Установи тип движения','На примере квадрата раздели движения, которые идут по вершинам в прежнем порядке, и те, которые обращают порядок. Первые — повороты, вторые — отражения.','Перенос на ненулевой вектор не может быть симметрией конечного набора вершин: повторяя его, мы ушли бы за границу фигуры.'),
               ('Считай только отличные повороты','У семиугольника полный оборот разбит на семь шагов. Выбери количество шагов от одного до шести. Седьмой шаг дал бы тождественное движение.','Не путай количество шагов полного оборота с количеством нетождественных поворотов.'),
               ('Примени формулу на новых данных','В третьем рисунке девять вершин, показан поворот на два шага. Посчитай все отражения и все нетождественные повороты девятиугольника.','Число 2n включает тождественное движение. Внутренних симметрий на одну меньше.')]
        probes=[('Сколько нетождественных поворотов имеет правильный семиугольник?','6','Есть семь возможных образов A, но один получается тождественным поворотом.'),('Сколько внутренних симметрий у правильного девятиугольника?','17','Девять осей и восемь нетождественных поворотов.')]
    titles=['Найди все оси','Проследи поворот вокруг T','Другой поворот и подсчёт']
    scenes=[drawing(t,*params) for t,params in zip(titles,cases,strict=True)]
    return clean(lesson(1273,part,327,task,proof,steps,scenes,probes,
         'Движение сохраняет расстояния и соседство вершин. Поворот сохраняет порядок обхода, отражение обращает его.',
         'Сначала посчитай оси, затем составь список разных поворотов до возвращения выбранной вершины в исходную.',
         'В первом чертеже выделены оси. В остальных стрелка показывает поворот луча TA к TE.',
         'Перечисли оси и повороты и объясни, почему других внутренних симметрий нет.',refs=[126,127]))


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    rows=[axes(),*[enumerate_symmetries(p) for p in 'абв']]
    raw=json.dumps({'bookId':BOOK,'lessons':rows},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==raw
    else:OUT.write_text(raw)
